/* From Uiverse.io by KINGFRESS - Tags: button */
.__UIV_SCOPE__ button {
  font-weight: bold;
  color: white;
  border-radius: 2rem;
  width: 95.02px;
  height: 42.66px;
  border: none;
  background-color: #3653F8;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ button .span-mother {
  display: flex;
  overflow: hidden;
}

.__UIV_SCOPE__ button:hover .span-mother {
  position: absolute;
}

.__UIV_SCOPE__ button:hover .span-mother span {
  transform: translateY(1.2em);
}

.__UIV_SCOPE__ button .span-mother span:nth-child(1) {
  transition: .2s;
}

.__UIV_SCOPE__ button .span-mother span:nth-child(2) {
  transition: .3s;
}

.__UIV_SCOPE__ button .span-mother span:nth-child(3) {
  transition: .4s;
}

.__UIV_SCOPE__ button .span-mother span:nth-child(4) {
  transition: .5s;
}

.__UIV_SCOPE__ button .span-mother span:nth-child(5) {
  transition: .6s;
}

.__UIV_SCOPE__ button .span-mother span:nth-child(6) {
  transition: .7s;
}

.__UIV_SCOPE__ button .span-mother2 {
  display: flex;
  position: absolute;
  overflow: hidden;
}

.__UIV_SCOPE__ button .span-mother2 span {
  transform: translateY(-1.2em);
}

.__UIV_SCOPE__ button:hover .span-mother2 span {
  transform: translateY(0);
}

.__UIV_SCOPE__ button .span-mother2 span {
  transition: .2s;
}

.__UIV_SCOPE__ button .span-mother2 span:nth-child(2) {
  transition: .3s;
}

.__UIV_SCOPE__ button .span-mother2 span:nth-child(3) {
  transition: .4s;
}

.__UIV_SCOPE__ button .span-mother2 span:nth-child(4) {
  transition: .5s;
}

.__UIV_SCOPE__ button .span-mother2 span:nth-child(5) {
  transition: .6s;
}

.__UIV_SCOPE__ button .span-mother2 span:nth-child(6) {
  transition: .7s;
}
